# Python program to find the single element using Bit Counting
class Solution:
    # Function to find the single number using the bit counting approach
    def single_number(self, nums: list[int]) -> int:
        result = 0

        # Iterate through all 32 bits of an integer
        for i in range(32):
            bit_sum = 0

            # Count how many numbers have the i-th bit set
            for num in nums:
                if (num >> i) & 1:
                    bit_sum += 1

            # If the sum is not a multiple of 3, the unique number has this bit set
            if bit_sum % 3 != 0:
                result |= (1 << i)

        # Python handles negative 32-bit integers differently, so we manually convert
        if result >= 2**31:
            result -= 2**32

        return result

if __name__ == "__main__":
    sol = Solution()
    arr = [2, 2, 3, 2]
    print(f"The single number is: {sol.single_number(arr)}")

